insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r28-v2','0.2.0','Lesson 6 step 1 of 6: What is the question asking for?','reading','guided_practice','Read LEARN FIRST and the worked example. Then, for each question phrase, choose the kind of information it asks for. Do not read the article yet.','Find the kind word first (account, example, caution, justification, option, or a word that means the same). The topic words are not the answer.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Phrase: \"mention of an option suited to buildings unable to carry a planted roof\". What kind of information is it?", "accepted_answers": ["E"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account (how something happens)"}, {"value": "B", "label": "B  an example (one real case)"}, {"value": "C", "label": "C  a caution (a warning or doubt)"}, {"value": "D", "label": "D  a justification (the reason someone gives)"}, {"value": "E", "label": "E  an option (another choice or solution)"}]}, {"id": "q2", "prompt": "Phrase: \"an account of how conditions after dark may weaken people''s capacity to cope with heat\". What kind of information is it?", "accepted_answers": ["A"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account (how something happens)"}, {"value": "B", "label": "B  an example (one real case)"}, {"value": "C", "label": "C  a caution (a warning or doubt)"}, {"value": "D", "label": "D  a justification (the reason someone gives)"}, {"value": "E", "label": "E  an option (another choice or solution)"}]}, {"id": "q3", "prompt": "Phrase: \"a warning that public money may be spent in the wrong places\". What kind of information is it?", "accepted_answers": ["C"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account (how something happens)"}, {"value": "B", "label": "B  an example (one real case)"}, {"value": "C", "label": "C  a caution (a warning or doubt)"}, {"value": "D", "label": "D  a justification (the reason someone gives)"}, {"value": "E", "label": "E  an option (another choice or solution)"}]}, {"id": "q4", "prompt": "Phrase: \"the reason councils give for charging owners of planted roofs lower fees\". What kind of information is it?", "accepted_answers": ["D"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account (how something happens)"}, {"value": "B", "label": "B  an example (one real case)"}, {"value": "C", "label": "C  a caution (a warning or doubt)"}, {"value": "D", "label": "D  a justification (the reason someone gives)"}, {"value": "E", "label": "E  an option (another choice or solution)"}]}, {"id": "q5", "prompt": "Phrase: \"an example of a way of coping with heat that makes the original problem worse\". What kind of information is it?", "accepted_answers": ["B"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account (how something happens)"}, {"value": "B", "label": "B  an example (one real case)"}, {"value": "C", "label": "C  a caution (a warning or doubt)"}, {"value": "D", "label": "D  a justification (the reason someone gives)"}, {"value": "E", "label": "E  an option (another choice or solution)"}]}, {"id": "q6", "prompt": "Phrase: \"a description of how plants carry heat away from a roof\". What kind of information is it?", "accepted_answers": ["A"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account (how something happens)"}, {"value": "B", "label": "B  an example (one real case)"}, {"value": "C", "label": "C  a caution (a warning or doubt)"}, {"value": "D", "label": "D  a justification (the reason someone gives)"}, {"value": "E", "label": "E  an option (another choice or solution)"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "teacher_notes": "1 E, an option. The kind word is ''option''. ''Buildings unable to carry a planted roof'' is only the topic.\n2 A, an account. ''An account of how'' asks for a cause leading to an effect: warm nights -> people cope less well.\n3 C, a caution. ''Warning'' means the same as caution: something may go wrong.\n4 D, a justification. ''The reason someone gives'' for an action is a justification.\n5 B, an example. The question wants one real case (a way of coping that backfires).\n6 A, an account. ''A description of how'' something happens is a process: water evaporates from leaves and takes heat with it.\nRead each explanation, then find the proof in the passage yourself.", "focus": "Select relevant information: identify the kind of information a matching-information question asks for before reading."}'::jsonb || jsonb_build_object('passage', to_jsonb('LEARN FIRST: name the KIND of information before you read

In matching-information questions you must find a paragraph that contains a certain KIND of information. The topic words are not enough. First find the word that names the kind.

The five kinds, and other words that mean the same:
A  an account: explanation of how/why, description of how, process  -> a cause leading to an effect
B  an example: instance, case, illustration  -> one real case of something more general
C  a caution: warning, doubt, concern  -> something may be wrong, limited or risky
D  a justification: the reason someone gives, argument for  -> why someone does something
E  an option: alternative, solution, choice  -> another way of dealing with a problem

WORKED EXAMPLE
Question phrase: "an explanation of how the soil layer keeps rooms cool"
1. Circle the kind word: "an explanation of how".
2. Ask: is it a process, cause -> effect? Yes: soil layer -> heat moves slowly -> rooms stay cool.
3. So the kind is A, an account. "Soil" and "rooms" are only the topic.

Now do the same for the six phrases. Do not read the article yet.'::text)),'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_06.json 0.2.0"}'::jsonb,'c74dd27f16ab777ad27ee0c41f83dd63a7ff71b27280ce128514e21d57a44092',true) on conflict (code) do nothing;
